def equation(eps, T, params):
    a0,a1,a2,a3,b,d,c,k,p = params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8]
    return a0 + a1*T + a2/T + a3*T**2 + b*eps*np.exp(-d*eps)/T + c*eps**p*np.exp(-k*eps/T)

